"""Explain fallback scope, helper reachability, verification limits and header layering."""
import json
from rewrite_c_beginner import rewrite, ROOT
ROWS={'os1617': ('큰 도구상자를 여러 층으로 나누면 각 층의 역할을 보기 쉬워요. 이 생성기는 두 자료형의 도구를 만들고, long 선택은 다른 층에 맡겨요.', 'fallback의 두 자료형 계열과 generic atomic64 연결을 이해합니다.', 'atomic/int와 atomic64/s64를 두 칸으로 그리고, atomic_long은 별도 생성기의 폭 선택으로 연결하세요.', ['gen-atomic-fallback.sh의 끝에는 표를 읽는 typed 반복문이 두 개 있어요. 하나는 atomic·int, 다른 하나는 atomic64·s64를 인자로 전달해요. 여기의 typed는 자료형이 정해진 함수 계열이라는 뜻이에요.', '각 계열의 85개 형태를 합하면 170개 typed 함수예요. 계측 생성기에서 세 계열 255개를 봤다고 이 파일에도 같은 세 반복이 있다고 추측하면 안 돼요. 파일마다 담당 범위가 달라요.', 'atomic64 생성 앞에는 CONFIG_GENERIC_ATOMIC64 조건의 include를 출력해요. 설정이 켜진 경우 asm-generic/atomic64.h를 포함하게 하는 C 전처리 지시문이에요.', '이 generic atomic64는 필요한 64비트 원자 연산을 잠금 같은 방법으로 제공하는 기반 구현과 연결돼요. 64라는 이름이 반드시 CPU의 단일 명령 하나를 뜻하지는 않아요. 128비트 명령을 실행하라는 설정도 아니에요.', 'atomic_long의 연결은 별도 gen-atomic-long.sh가 담당해요. 그 결과는 커널의 long 폭에 맞춰 raw_atomic64 또는 raw_atomic 계열을 고르는 wrapper예요. 이 fallback 파일의 세 번째 typed 반복문이 아니에요.', '그림으로는 generic 기반 연산 → fallback의 API 보완 → long 타입 선택으로 나누어 보세요. include 조건은 컴파일 과정의 선택이며 원자 함수를 부를 때마다 파일을 읽는 실행 분기가 아니에요.'], [('이 fallback 생성기의 typed 출력 계열은 무엇인가요?', ['atomic·atomic64·atomic_long 세 반복이 모두 있어요', 'atomic와 atomic64 두 계열이에요'], '정답은 두 번째예요. 끝의 표 반복문은 atomic/int와 atomic64/s64를 전달해요. long 계열 선택은 별도 생성기의 역할이에요.'), ('CONFIG_GENERIC_ATOMIC64 조건의 include는 무엇과 연결되나요?', ['generic atomic64 기반 연산의 선택과 연결돼요', '모든 CPU에서 128비트 명령을 무조건 실행해요'], '정답은 첫 번째예요. 해당 설정이면 generic atomic64 헤더를 포함해요. 설정에 따른 구현 연결을 더 큰 폭의 하드웨어 명령 실행으로 해석하면 안 돼요.')]), 'os1618': ('조리법 책에 방법이 적혀 있어도 오늘 그 요리를 했다는 뜻은 아니에요. 함수도 정의되어 있다는 사실과 실제로 불렸다는 사실을 나눠 봐야 해요.', '도우미의 정의와 실제 호출 경로를 구별합니다.', '함수 정의 목록과 실행 본문의 호출 목록을 두 칸에 적으세요. gen_basic_fallbacks가 정의된 줄과 실제 본문에서 부르는 이름을 구별하세요.', ['함수 정의는 나중에 그 이름을 부르면 무엇을 할지 적어 놓는 것이에요. 쉘이 파일을 읽어 함수를 정의했다고 그 본문까지 전부 실행하는 것은 아니에요. 실제 호출 명령이 필요해요.', '이 스크립트에는 gen_basic_fallbacks와 gen_order_fallbacks라는 정의가 있어요. 그러나 본문의 generic 반복문은 gen_xchg_fallbacks와 gen_try_cmpxchg_order_fallbacks 같은 이름을 불러요. 비슷해 보여도 서로 다른 함수예요.', 'gen_basic_fallbacks를 실제 부르면 raw 이름의 _acquire·_release·_relaxed를 기본 arch 함수에 연결하는 #define 세 줄을 출력해요. basename이 demo라면 raw_demo_acquire를 arch_demo에 연결하는 식이에요.', '이것은 코드 이름의 별칭을 만드는 출력이에요. 실행 중 객체를 찾아 숫자를 0으로 초기화하는 코드가 아니에요. 또한 도우미를 읽어 출력 모양을 알았다는 사실과 본 생성 작업에서 호출했다는 사실도 달라요.', 'gen_order_fallbacks는 relaxed 기반 보강이나 직접 제공 형태를 선택하는 코드를 출력하도록 정의돼 있어요. 어떤 도우미가 실행됐는지는 실제 호출 이름과 함수 안에서 이어 부르는 이름들을 따라가야 해요. 이런 연결 그림을 호출 관계도라고 해요.', '검사 기록에도 소스로 읽은 함수와 실제로 실행한 함수를 구별해 적어야 해요. 사용되지 않는 정의가 보인다고 무조건 잘못된 결과를 만든다고 할 수도 없고, 모든 경로를 실행했다고 할 수도 없어요.'], [('쉘 파일에 도우미 함수가 정의되어 있으면 이번 실행에서 반드시 불리나요?', ['네. 쉘이 모든 정의의 본문을 자동 실행해요', '아니요. 실제로 그 함수를 부르는 코드가 있는지 봐야 해요'], '정답은 두 번째예요. 조리법이 책에 있는 것과 요리를 하는 것이 다르듯 정의와 호출은 달라요. 본문과 이어지는 함수 호출을 따라가세요.'), ('gen_basic_fallbacks가 출력하는 것은 무엇인가요?', ['순서 꼬리표가 있는 raw 이름을 기본 arch 함수에 연결하는 별칭이에요', '모든 객체의 숫자를 실행 중 0으로 초기화해요'], '정답은 첫 번째예요. 출력은 #define 이름 연결이에요. 생성된 코드 이름과 실제 저장 객체의 값 변경은 다른 일입니다.')]), 'os1619': ('자전거 조립이 끝난 것, 평지에서 한 번 탄 것, 모든 길에서 안전한 것은 각각 다른 확인이에요. 코드 검사도 무엇을 확인했는지 범위를 나눠야 해요.', '생성·컴파일·선택 실행·메모리 순서 검증의 차이를 이해합니다.', '생성 일치 / 컴파일 / 지정 입력 실행 / 메모리 모델 분석 / 해설 검토의 다섯 칸에 각각 확인하는 대상을 적으세요.', ['생성 결과가 원문과 같다는 검사는 같은 코드 글자를 만들었는지 보는 일이에요. 계산을 실제로 실행하거나 여러 CPU의 모든 동작을 확인하는 일과는 달라요.', '컴파일은 문법과 타입 등의 조건에 맞춰 코드를 번역하는 과정이에요. 170개 함수가 컴파일돼도 각 함수의 모든 입력이 실행되지는 않아요. 실행했다면 함수 이름과 실제 입력을 따로 기록해야 해요.', '선택 실행 모델은 정해진 상황을 만들어 볼 수 있어요. 예를 들어 첫 비교가 실패하면서 예상 값이 0으로 바뀌게 만들면 다음 반복이 다시 조건을 검사하는지 확인할 수 있어요. 이것은 결정한 실패 상황을 흉내 낸 모델이에요.', 'fence hook을 세어 앞 장벽과 뒤 장벽을 거쳤는지 기록할 수도 있어요. 하지만 그 기록은 실제 CPU에서 다른 메모리 접근이 어떻게 관찰되는지 모두 분석한 결과가 아니에요. LKMM은 커널의 메모리 순서 모델이고 그 모델 분석은 별도예요.', 'ASan이나 UBSan 같은 검사 도구도 실행된 사례에서 문제를 찾는 데 도움을 줘요. 통과 횟수가 크더라도 모든 입력·모든 CPU·모든 실행 순서·공정성을 증명하지는 않아요. 공정성은 어떤 작업만 계속 기회를 잃지 않는지에 관한 성질이에요.', '마지막으로 컴파일러는 초보자를 위한 해설과 답지를 대신 완성하지 않아요. 무엇이 필요한지, 어떤 원리인지, 왜 오답인지 설명을 따로 작성하고 검토해야 해요. 이 수업은 검사의 뜻을 배우며 과거 검사 횟수를 이번 실행 결과로 다시 주장하지 않아요.'], [('모델에서 fence hook 개수를 확인하면 실제 LKMM 분석을 실행한 것인가요?', ['네. 모든 CPU의 가능한 실행을 이미 열거한 것이에요', '아니요. 지정된 모델에서 어느 경로를 거쳤는지 확인한 것이에요'], '정답은 두 번째예요. 장벽 호출 기록과 메모리 순서 모델의 가능한 관찰 결과 분석은 다릅니다. 실제로 확인한 검사 범위만 결과로 말해야 해요.'), ('전체 코드가 컴파일되면 모든 구현의 해설과 문제도 완성됐나요?', ['아니요. 설명과 문제는 별도로 작성하고 검토해야 해요', '네. 컴파일러가 모든 기술의 답지를 자동으로 써요'], '정답은 첫 번째예요. 코드를 번역할 수 있다는 사실은 독자가 원리와 이유를 이해할 설명이 준비됐다는 뜻이 아니에요. 내용 완성과 빌드 성공을 구별하세요.')]), 'os1620': ('도구를 쓰려면 바탕 부품, 부족한 기능을 보완하는 부품, 사용자용 손잡이를 차례로 연결할 수 있어요. 공통 atomic 헤더는 이런 층의 코드를 모아 줘요.', '공통 헤더의 포함 순서와 실행 호출 경로를 구별합니다.', '헤더 연결은 arch fallback → long → instrumented, 호출 추적은 일반 API → raw → 선택된 arch 구현이라고 두 줄로 적으세요.', ['include/linux/atomic.h는 원자 연산에 필요한 정의들을 모으는 공통 헤더예요. 먼저 자료형과 아키텍처의 atomic·barrier 정의 등을 포함하고 공통 도우미를 정의해요.', '도우미에는 조건을 만족할 때까지 값을 관찰하는 매크로와 relaxed 연산에 순서를 보강하는 장벽 연결 등이 있어요. 모든 CPU의 알고리즘을 이 파일 한 곳에 직접 적는 방식은 아니에요.', '파일 끝의 세 include는 atomic-arch-fallback.h, atomic-long.h, atomic-instrumented.h 순서예요. 첫째는 기반 연산으로 부족한 API를 보완하고, 둘째는 long 폭에 맞는 계열을 선택하고, 셋째는 일반 API의 계측 경로를 붙여요.', '이 순서는 C 전처리에서 필요한 선언과 정의를 연결하는 순서예요. 함수가 불릴 때마다 디스크에서 헤더를 다시 읽어 실행하는 순서가 아니에요. include는 C 코드를 준비하는 단계의 연결이에요.', '실제 호출을 알아보려면 일반 atomic 함수에서 raw 함수로, 다시 선택된 arch 구현으로 따라가 보세요. 생성된 fallback 안에서 또 다른 raw 기반 함수를 부를 수도 있어요. 정의된 이름의 연결과 실제 명령을 구별하며 읽어야 해요.', '공통 헤더의 연결을 이해했다고 포함된 큰 파일의 모든 구현까지 설명한 것은 아니에요. 각 층에서 제공하는 타입·원자성·순서·계측의 역할을 연결한 뒤 필요한 함수 본문을 따로 읽어야 해요.'], [('공통 헤더의 마지막 연결에서 instrumented 헤더는 long 헤더보다 뒤에 있나요?', ['아니요. 계측 헤더만 있고 raw 계층은 없어요', '네. fallback, long, instrumented 순서로 포함해요'], '정답은 두 번째예요. 원문 마지막 세 include의 순서예요. 일반 계측 경로가 호출할 raw 연결을 앞의 층에서 마련하는 구조로 읽을 수 있어요.'), ('원자 함수를 호출할 때마다 include가 다시 실행되나요?', ['아니요. include는 C 전처리·컴파일 과정의 코드 연결이에요', '네. 실행할 때마다 원문 헤더 파일을 해석해요'], '정답은 첫 번째예요. 헤더로 코드를 준비하는 단계와 만들어진 함수가 실행되는 단계는 달라요. 파일 연결 순서를 매 호출의 파일 읽기로 해석하지 마세요.')])}
def run():
    additions={}
    for path in (ROOT/'course/lesson-parts').glob('*.json'):
        for lesson in json.loads(path.read_text(encoding='utf-8')):
            key=lesson['id']
            if key not in ROWS:continue
            practice=dict(lesson.get('practice',{}));practice['expected']=ROWS[key][2]
            additions[key]=dict(concepts=[],reading_support=None,deep_dive=[],goal=ROWS[key][1],experiment={'title':'종이에 따라 해 보기','steps':[ROWS[key][2]]},practice=practice)
    return rewrite(ROWS,'tools/rewrite_os_beginner_400.py',additions)
if __name__=='__main__':print(json.dumps(run(),ensure_ascii=False))
